package local.z6panel;

import android.app.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.util.LruCache;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Eight visible thumbnails, stable photo focus, and explicit confirmed batch removal. */
final class WallpaperLibrary {
 interface Host {void open(String id);void receive();void importFiles();void back();}
 private final Activity activity;private final WallpaperStore store;private final Host host;private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(10),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-thumbnails"));
 private final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getAllocationByteCount();}protected void entryRemoved(boolean evicted,String key,Bitmap old,Bitmap replacement){if(old!=replacement&&!old.isRecycled())old.recycle();}};
 private final Set<String> selected=new LinkedHashSet<>();private final List<ImageView> images=new ArrayList<>();private final Map<String,LinearLayout> cards=new LinkedHashMap<>();private final Map<String,TextView> labels=new HashMap<>();
 private List<WallpaperStore.Photo> photos=Collections.emptyList();private int offset,epoch;private boolean visible,selecting,busy;private String focus="";private LinearLayout root,grid;private Button selectButton,deleteButton,allButton;private AlertDialog confirmation;TextView status;
 WallpaperLibrary(Activity a,WallpaperStore s,Host h){activity=a;store=s;host=h;worker.allowCoreThreadTimeOut(true);}
 private int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFBBC3CC);return t;}
 private GradientDrawable background(boolean focused,boolean checked){GradientDrawable d=new GradientDrawable();d.setColor(checked?0xFF2A4143:0xFF222E38);d.setCornerRadius(dp(5));if(focused)d.setStroke(dp(2),0xFFD2DFE5);return d;}
 private Button button(LinearLayout row,String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(12);b.setTextColor(Color.WHITE);b.setPadding(dp(3),0,dp(3),0);StateListDrawable state=new StateListDrawable();state.addState(new int[]{android.R.attr.state_focused},background(true,false));state.addState(new int[]{},background(false,false));b.setBackground(state);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(38),1);p.setMargins(dp(3),0,dp(3),0);row.addView(b,p);b.setOnClickListener(v->{if(busy){status.setText("Espera a que termine la operación");return;}action.run();});return b;}
 void show(){hide();visible=true;final int token=epoch;root=new LinearLayout(activity);root.setOrientation(1);root.setPadding(dp(24),dp(12),dp(24),dp(12));root.setBackgroundColor(0xFF121722);TextView heading=text("Mi biblioteca",22);heading.setTextColor(Color.WHITE);root.addView(heading);status=text("Cargando fotos…",12);root.addView(status,new LinearLayout.LayoutParams(-1,dp(24)));
  LinearLayout tools=new LinearLayout(activity);root.addView(tools);button(tools,"Recibir",host::receive);button(tools,"Importar",host::importFiles);selectButton=button(tools,selecting?"Cancelar selección":"Seleccionar",()->{selecting=!selecting;if(!selecting)selected.clear();refreshSelection();});deleteButton=button(tools,"Eliminar (0)",()->confirm(new ArrayList<>(selected)));allButton=button(tools,"Eliminar todas",()->{ArrayList<String> ids=new ArrayList<>();for(WallpaperStore.Photo p:photos)ids.add(p.id);confirm(ids);});
  grid=new LinearLayout(activity);grid.setOrientation(1);LinearLayout.LayoutParams g=new LinearLayout.LayoutParams(-1,0,1);g.topMargin=dp(7);g.bottomMargin=dp(7);root.addView(grid,g);
  LinearLayout footer=new LinearLayout(activity);root.addView(footer);button(footer,"Anteriores",()->{if(offset>0){offset=Math.max(0,offset-8);focus="";show();}});TextView pages=text("",12);pages.setGravity(Gravity.CENTER);footer.addView(pages,new LinearLayout.LayoutParams(0,dp(38),1));button(footer,"Siguientes",()->{if(offset+8<photos.size()){offset+=8;focus="";show();}});button(footer,"Volver",host::back);activity.setContentView(root);
  worker.execute(()->{try{List<WallpaperStore.Photo> loaded=store.photos();ui.post(()->{if(!visible||token!=epoch)return;photos=loaded;Set<String> ids=new HashSet<>();for(WallpaperStore.Photo p:loaded)ids.add(p.id);selected.retainAll(ids);offset=Math.min(offset,Math.max(0,((loaded.size()-1)/8)*8));pages.setText((offset/8+1)+" / "+Math.max(1,(loaded.size()+7)/8));status.setText(loaded.size()+" / 50 fotos · copia privada de Z6 · máximo 100 MB");draw(token);});}catch(Exception e){ui.post(()->{if(visible&&token==epoch)status.setText(e.getMessage());});}});
 }
 private void draw(int token){grid.removeAllViews();cards.clear();labels.clear();if(photos.isEmpty()){TextView empty=text("Tu biblioteca está vacía. Recibe o importa una foto.",16);empty.setGravity(Gravity.CENTER);grid.addView(empty,new LinearLayout.LayoutParams(-1,-1));refreshSelection();return;}for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(activity);grid.addView(line,new LinearLayout.LayoutParams(-1,0,1));for(int col=0;col<4;col++){int index=offset+row*4+col;LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setPadding(dp(5),dp(5),dp(5),dp(5));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));line.addView(card,p);if(index>=photos.size())continue;WallpaperStore.Photo photo=photos.get(index);cards.put(photo.id,card);card.setFocusable(true);card.setClickable(true);card.setContentDescription(photo.name+" · "+photo.dimensions());card.setBackground(background(false,selected.contains(photo.id)));ImageView thumb=new ImageView(activity);thumb.setBackgroundColor(WallpaperImages.DARK);thumb.setScaleType(photo.fit.equals("contain")?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);card.addView(thumb,new LinearLayout.LayoutParams(-1,0,1));images.add(thumb);TextView label=text(photo.name,12);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.put(photo.id,label);card.addView(label);TextView info=text(photo.dimensions()+" · "+WallpaperImages.bytes(photo.file.length()),10);card.addView(info);card.setOnFocusChangeListener((v,focused)->{if(focused)focus=photo.id;card.setBackground(background(focused,selected.contains(photo.id)));});card.setOnClickListener(v->{if(busy)return;if(selecting){if(!selected.add(photo.id))selected.remove(photo.id);refreshSelection();}else{focus=photo.id;host.open(photo.id);}});Bitmap found=cache.get(photo.id);if(found!=null)thumb.setImageBitmap(found);else loadThumbnail(photo,thumb,token);}}
  refreshSelection();LinearLayout target=cards.get(focus);if(target==null&&!cards.isEmpty())target=cards.values().iterator().next();if(target!=null)target.requestFocus();
 }
 private void loadThumbnail(WallpaperStore.Photo photo,ImageView view,int token){try{worker.execute(()->{if(!visible||token!=epoch)return;Bitmap bitmap=null;try{bitmap=store.thumbnail(photo);}catch(Exception ignored){}final Bitmap ready=bitmap;ui.post(()->{if(ready==null)return;if(!visible||token!=epoch){ready.recycle();return;}cache.put(photo.id,ready);view.setImageBitmap(ready);});});}catch(RejectedExecutionException busy){status.setText("Espera a que termine la operación actual");}}
 private void refreshSelection(){if(selectButton==null)return;selectButton.setText(selecting?"Cancelar selección":"Seleccionar");deleteButton.setText("Eliminar ("+selected.size()+")");deleteButton.setEnabled(!busy&&!selected.isEmpty());allButton.setEnabled(!busy&&!photos.isEmpty());for(Map.Entry<String,LinearLayout> e:cards.entrySet()){boolean marked=selected.contains(e.getKey());e.getValue().setBackground(background(e.getValue().hasFocus(),marked));TextView label=labels.get(e.getKey());for(WallpaperStore.Photo p:photos)if(p.id.equals(e.getKey())){label.setText((marked?"✓ ":"")+p.name);break;}}}
 private void confirm(List<String> ids){if(ids.isEmpty())return;confirmation=new AlertDialog.Builder(activity).setTitle("¿Eliminar "+ids.size()+(ids.size()==1?" foto?":" fotos?")).setMessage("Solo se eliminarán las copias de Z6. Los originales del celular o USB se conservan.").setPositiveButton("Eliminar",(d,w)->remove(ids)).setNegativeButton("Cancelar",null).create();confirmation.show();}
 private void remove(List<String> ids){busy=true;refreshSelection();status.setText("Eliminando…");worker.execute(()->{String result;try{result=store.removeMany(ids).message();}catch(Exception e){result=e.getMessage();}final String message=result;ui.post(()->{busy=false;selected.clear();if(visible){show();final int token=epoch;ui.postDelayed(()->{if(visible&&token==epoch)status.setText(message);},300);}});});}
 void hide(){visible=false;epoch++;if(!busy)worker.getQueue().clear();ui.removeCallbacksAndMessages(null);if(confirmation!=null&&confirmation.isShowing())confirmation.dismiss();for(ImageView image:images)image.setImageDrawable(null);images.clear();cards.clear();labels.clear();cache.evictAll();}
 boolean busy(){return busy;}
 void trim(){epoch++;if(!busy)worker.getQueue().clear();for(ImageView image:images)image.setImageDrawable(null);cache.evictAll();}
 void destroy(){hide();worker.shutdownNow();}
 JSONObject inspect()throws JSONException{JSONArray ids=new JSONArray();for(String id:cards.keySet())ids.put(id);return new JSONObject().put("page",offset/8+1).put("visibleIds",ids).put("selectionCount",selected.size()).put("selecting",selecting).put("thumbnailBytes",cache.size()).put("dialog",confirmation!=null&&confirmation.isShowing()).put("busy",busy);}
 String action(String action){if(!visible)return "NOT_VISIBLE";if(action.equals("select_toggle")){selecting=!selecting;if(!selecting)selected.clear();refreshSelection();}else if(action.startsWith("mark:")){String id=action.substring(5);if(store.find(id)==null)return "INVALID";selecting=true;if(!selected.add(id))selected.remove(id);refreshSelection();}else if(action.equals("delete_selected"))confirm(new ArrayList<>(selected));else if(action.equals("delete_all")){ArrayList<String> ids=new ArrayList<>();for(WallpaperStore.Photo p:photos)ids.add(p.id);confirm(ids);}else if(action.equals("confirm_delete")||action.equals("cancel_delete")){if(confirmation==null||!confirmation.isShowing())return "NO_DIALOG";confirmation.getButton(action.equals("confirm_delete")?AlertDialog.BUTTON_POSITIVE:AlertDialog.BUTTON_NEGATIVE).performClick();}else if(action.equals("next_page")){if(offset+8<photos.size()){offset+=8;focus="";show();}}else if(action.equals("previous_page")){offset=Math.max(0,offset-8);focus="";show();}else return "NOT_FOUND";return "OK";}
}
